const cfg = $('Config').first().json;

function safeNodeJson(name) {
  try {
    return $(name).first()?.json ?? {};
  } catch (error) {
    return {};
  }
}

const todayReport = safeNodeJson('Get Today Sales');
const monthReport = safeNodeJson('Get Month Sales');
const goalsReport = safeNodeJson('Get Goals Report');
const inventoryAlerts = safeNodeJson('Get Inventory Alerts');

function toNumber(value) {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.items)) return value.items;
  if (Array.isArray(value.points)) return value.points;
  return [];
}

function normalizeDailySales(raw) {
  return asArray(raw).reduce((sum, point) => sum + toNumber(point.total ?? point.totalSales ?? point.amount), 0);
}

function normalizeMonthlySales(raw) {
  return asArray(raw).reduce((sum, point) => sum + toNumber(point.total ?? point.totalSales ?? point.amount), 0);
}

function normalizeGoals(raw) {
  const items = asArray(raw.items ?? raw);
  return items.map((item) => ({
    softwareName: item.softwareName ?? 'Producto',
    achieved: Boolean(item.achieved),
    variance: toNumber(item.variance)
  }));
}

function normalizeInventory(raw) {
  return asArray(raw).map((item) => ({
    name: item.name ?? item.softwareName ?? item.title ?? 'Producto sin nombre'
  }));
}

function money(value) {
  return '$' + toNumber(value).toFixed(2);
}

function percent(value) {
  return toNumber(value).toFixed(1) + '%';
}

function formatDateISO(date) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

function addDays(date, days) {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

const todaySales = normalizeDailySales(todayReport);
const monthSales = normalizeMonthlySales(monthReport);
const monthlyGoal = toNumber(cfg.monthlyGoal);
const remainingToGoal = Math.max(monthlyGoal - monthSales, 0);
const progressPercent = monthlyGoal > 0 ? (monthSales / monthlyGoal) * 100 : 0;

const today = new Date(cfg.todayDate + 'T00:00:00');
const dayOfMonth = today.getDate();
const endOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0);
const daysInMonth = endOfMonth.getDate();
const expectedPercentToday = daysInMonth > 0 ? (dayOfMonth / daysInMonth) * 100 : 0;
const isBehindTarget = progressPercent < expectedPercentToday;
const projectedClose = dayOfMonth > 0 ? (monthSales / dayOfMonth) * daysInMonth : monthSales;

const goals = normalizeGoals(goalsReport);
const topProducts = goals.filter((item) => !item.achieved).sort((a, b) => a.variance - b.variance).slice(0, 5).map((item) => item.softwareName);
const zeroSalesProducts = normalizeInventory(inventoryAlerts).slice(0, 5).map((item) => item.name);

const todayStr = formatDateISO(today);
const expenses = [
  { name: 'Internet', amount: 50, dueDate: todayStr, status: 'pending' },
  { name: 'Hosting', amount: 20, dueDate: todayStr, status: 'pending' },
  { name: 'Publicidad', amount: 100, dueDate: formatDateISO(addDays(today, 2)), status: 'pending' }
];
const nextThreeStr = formatDateISO(addDays(today, 3));
const pendingExpenses = expenses.filter((expense) => expense.status !== 'paid');
const dueToday = pendingExpenses.filter((expense) => expense.dueDate === todayStr);
const overdueExpenses = pendingExpenses.filter((expense) => expense.dueDate < todayStr);
const nextExpenses = pendingExpenses.filter((expense) => expense.dueDate > todayStr && expense.dueDate <= nextThreeStr);
const totalExpensesToday = dueToday.reduce((sum, expense) => sum + expense.amount, 0);
const totalExpensesUpcoming = nextExpenses.reduce((sum, expense) => sum + expense.amount, 0);

let priorityMessage = 'Enfoque en crecimiento y seguimiento comercial del equipo.';
if (overdueExpenses.length > 0) {
  priorityMessage = 'ALERTA CRITICA: hay pagos vencidos. Prioridad total en liquidez y regularizacion inmediata.';
} else if (dueToday.length > 0) {
  priorityMessage = 'Enfoque en liquidez: hay pagos importantes hoy y se debe cuidar caja desde temprano.';
} else if (todaySales === 0 || isBehindTarget) {
  priorityMessage = 'Enfoque en ventas: el ritmo comercial va por debajo de lo esperado y requiere accion inmediata.';
}

const todayLines = dueToday.length ? dueToday.map((item) => '- ' + item.name + ': ' + money(item.amount)).join('\n') : 'Sin pagos hoy';
const overdueLines = overdueExpenses.length ? overdueExpenses.map((item) => '- ' + item.name + ': ' + money(item.amount)).join('\n') : 'Sin vencidos';
const upcomingLines = nextExpenses.length ? nextExpenses.map((item) => '- ' + item.name + ': ' + money(item.amount) + ' (' + item.dueDate + ')').join('\n') : 'Sin pagos proximos';
const topLines = topProducts.length ? topProducts.map((item, index) => (index + 1) + '. ' + item).join('\n') : 'Sin productos destacados';
const zeroLines = zeroSalesProducts.length ? zeroSalesProducts.map((item) => '- ' + item).join('\n') : 'Sin productos sin movimiento';

const message = '?? <b>REPORTE EJECUTIVO DISMAL</b>\n\nBuenos dias.\n\n?? <b>Meta mensual:</b> ' + money(monthlyGoal) + '\n?? <b>Venta acumulada:</b> ' + money(monthSales) + '\n?? <b>Venta hoy:</b> ' + money(todaySales) + '\n? <b>Avance:</b> ' + percent(progressPercent) + '\n?? <b>Ritmo esperado:</b> ' + percent(expectedPercentToday) + '\n?? <b>Faltante:</b> ' + money(remainingToGoal) + '\n?? <b>Proyeccion:</b> ' + money(projectedClose) + '\n\n?? <b>PAGOS IMPORTANTES:</b>\n\n<b>Hoy:</b>\n' + todayLines + '\n\n<b>Vencidos:</b>\n' + overdueLines + '\n\n<b>Proximos:</b>\n' + upcomingLines + '\n\n?? <b>Productos a empujar:</b>\n' + topLines + '\n\n?? <b>Sin movimiento:</b>\n' + zeroLines + '\n\n?? <b>PRIORIDAD DEL DIA:</b>\n' + priorityMessage;

return [{ json: { message, todaySales, monthSales, monthlyGoal, remainingToGoal, progressPercent, expectedPercentToday, isBehindTarget, projectedClose, totalExpensesToday, totalExpensesUpcoming, overdueExpensesCount: overdueExpenses.length, dueTodayCount: dueToday.length, nextExpensesCount: nextExpenses.length, topProducts, zeroSalesProducts } }];
